(async () => {
const isOneByOne = (w, h) => Number(w) === 1 && Number(h) === 1;

  function buildTokenUpdate(actor) {
    const size = actor.system?.details?.size;
    if (!size) return null;

    const pt = actor.prototypeToken;
    let width = pt.width ?? 1;
    let height = pt.height ?? 1;
    const update = { _id: actor.id };

    if (isOneByOne(width, height)) {
      if (size === "L") { width = 1.5; height = 1.5; }
      else if (size === "G") { width = 2; height = 2; }
      else if (size === "I") { width = 3; height = 3; }
    }

    update["prototypeToken.width"] = width;
    update["prototypeToken.height"] = height;
    update["prototypeToken.texture.fit"] = "fill";

    const stillOne = isOneByOne(width, height);
    let scale = null;
    if (size === "T") scale = 0.5;
    else if (size === "S") scale = 0.75;
    else if (size === "M" && stillOne) scale = 0.9;

    if (scale !== null) {
      update["prototypeToken.texture.scaleX"] = scale;
      update["prototypeToken.texture.scaleY"] = scale;
    }

    return update;
  }

  const packs = game.packs.filter(p => p.metadata.type === "Actor");
  if (!packs.length) {
    return ui.notifications.info("No Actor compendium packs found.");
  }

  const locked = packs.filter(p => p.locked);
  if (locked.length) {
    const names = locked.map(p => p.metadata.label).join(", ");
    ui.notifications.warn(`Skipping locked Actor pack(s): ${names}`);
  }

  let totalUpdated = 0;
  let packsUpdated = 0;

  for (const pack of packs) {
    if (pack.locked) continue;

    const docs = await pack.getDocuments();
    const updates = docs.map(buildTokenUpdate).filter(Boolean);
    if (!updates.length) continue;

    await Actor.updateDocuments(updates, { pack: pack.collection });
    totalUpdated += updates.length;
    packsUpdated++;
    console.log(`Updated ${updates.length} actor(s) in ${pack.metadata.label}`);
  }

  ui.notifications.info(`Updated ${totalUpdated} actor(s) across ${packsUpdated} unlocked Actor pack(s).`);
})();
